class State:
    def __init__(self):
        self.next = []

class CharState(State):
    def __init__(self, char, target):
        super().__init__()
        self.char = char
        self.target = target

class DotState(State):
    def __init__(self, target):
        super().__init__()
        self.target = target

class ClassState(State):
    def __init__(self, ranges, negate, target):
        super().__init__()
        self.ranges = ranges
        self.negate = negate
        self.target = target

    def matches(self, char):
        cp = ord(char)
        in_range = False
        for start, end in self.ranges:
            if start <= cp <= end:
                in_range = True
                break
        return not in_range if self.negate else in_range

class SplitState(State):
    def __init__(self, s1, s2):
        super().__init__()
        self.s1 = s1
        self.s2 = s2

class AnchorStartState(State):
    def __init__(self, target):
        super().__init__()
        self.target = target

class AnchorEndState(State):
    def __init__(self, target):
        super().__init__()
        self.target = target

class Fragment:
    def __init__(self, start, end):
        self.start = start
        self.end = end

class Parser:
    def __init__(self, pattern):
        self.pattern = pattern
        self.pos = 0

    def parse_expr(self):
        nodes = [self.parse_term()]
        while self.pos < len(self.pattern) and self.pattern[self.pos] == '|':
            self.pos += 1
            nodes.append(self.parse_term())
        if len(nodes) == 1:
            return nodes[0]

        start = State()
        end = State()
        current = start
        for i in range(len(nodes)):
            node = nodes[i]
            new_split = SplitState(node.start, State())
            if i == 0:
                start = new_split
            else:
                current.next.append(new_split)
            node.end.next.append(end)
            current = new_split.s2
        # If there were more than 2, the last s2 should also lead to end
        # But the loop above needs better logic. Let's simplify.

        start_node = State()
        end_node = State()
        for node in nodes:
            s = SplitState(node.start, State())
            start_node.next.append(s)
            node.end.next.append(end_node)
            # s.s2 is just a dummy here, let's fix it.
            # Correct Thompson's alternation:
            # start -> s1, start -> s2, ..., s1_end -> end, s2_end -> end

        start_alt = State()
        end_alt = State()
        for node in nodes:
            start_alt.next.append(SplitState(node.start, State())) # This is wrong
        return Fragment(start_alt, end_alt)

    def parse_expr_fixed(self):
        node1 = self.parse_term()
        if self.pos < len(self.pattern) and self.pattern[self.pos] == '|':
            self.pos += 1
            node2 = self.parse_expr_fixed()
            start = SplitState(node1.start, node2.start)
            end = State()
            node1.end.next.append(end)
            node2.end.next.append(end)
            return Fragment(start, end)
        return node1

    def parse_term(self):
        start = State()
        curr = start
        while self.pos < len(self.pattern) and self.pattern[self.pos] not in '|)':
            node = self.parse_factor()
            if curr == start:
                start = node.start
                curr = node.end
            else:
                curr.next.append(node.start)
                curr = node.end
        if curr == start:
            s = State()
            return Fragment(s, s)
        return Fragment(start, curr)

    def parse_factor(self):
        atom = self.parse_atom()
        if self.pos < len(self.pattern) and self.pattern[self.pos] in '*+?':
            op = self.pattern[self.pos]
            self.pos += 1
            end = State()
            if op == '*':
                start = SplitState(atom.start, end)
                atom.end.next.append(atom.start)
                atom.end.next.append(end)
                return Fragment(start, end)
            elif op == '+':
                start = atom.start
                atom.end.next.append(atom.start)
                atom.end.next.append(end)
                return Fragment(start, end)
            elif op == '?':
                start = SplitState(atom.start, end)
                atom.end.next.append(end)
                return Fragment(start, end)
        return atom

    def parse_atom(self):
        if self.pos >= len(self.pattern):
            raise ValueError("Unexpected end of pattern")

        char = self.pattern[self.pos]
        if char == '(':
            self.pos += 1
            expr = self.parse_expr_fixed()
            if self.pos >= len(self.pattern) or self.pattern[self.pos] != ')':
                raise ValueError("Unclosed parenthesis")
            self.pos += 1
            return expr
        elif char == '[':
            start_pos = self.pos
            ranges, negate, new_pos = self.parse_class()
            self.pos = new_pos
            s = State()
            e = State()
            # ClassState must be linked
            # We can't easily put ClassState in Fragment because it's a transition.
            # Let's make ClassState have a target.
            cls = ClassState(ranges, negate, e)
            s.next.append(cls) # This is not quite right, ClassState is not an epsilon transition.
            # Thompson: a Fragment is start -> (transitions) -> end.
            # For a single char/class: start --char--> end.
            # To keep it consistent, we'll make ClassState's 'start' be a special case.
            return Fragment(cls, e)
        elif char == '.':
            self.pos += 1
            e = State()
            return Fragment(DotState(e), e)
        elif char == '\\':
            if self.pos + 1 >= len(self.pattern):
                raise ValueError("Trailing backslash")
            c = self.pattern[self.pos + 1]
            self.pos += 2
            e = State()
            return Fragment(CharState(c, e), e)
        elif char == '^':
            self.pos += 1
            e = State()
            return Fragment(AnchorStartState(e), e)
        elif char == '$':
            self.pos += 1
            e = State()
            return Fragment(AnchorEndState(e), e)
        elif char in '*+?|)':
            raise ValueError(f"Unexpected character {char}")
        else:
            self.pos += 1
            e = State()
            return Fragment(CharState(char, e), e)

    def parse_class(self):
        pos = self.pos + 1
        negate = False
        if pos < len(self.pattern) and self.pattern[pos] == '^':
            negate = True
            pos += 1
        if pos >= len(self.pattern) or (pos < len(self.pattern) and self.pattern[pos] == ']'):
            if pos < len(self.pattern) and self.pattern[pos] == ']':
                raise ValueError("Empty character class")
            raise ValueError("Unclosed [")
        ranges = []
        while pos < len(self.pattern):
            if self.pattern[pos] == '\\':
                if pos + 1 >= len(self.pattern): raise ValueError("Trailing backslash")
                char = self.pattern[pos+1]
                pos += 2
            else:
                char = self.pattern[pos]
                pos += 1
                if char == ']':
                    return ranges, negate, pos
            if pos < len(self.pattern) and self.pattern[pos] == '-':
                if pos + 1 < len(self.pattern) and self.pattern[pos+1] != ']':
                    pos += 1
                    if self.pattern[pos] == '\\':
                        if pos + 1 >= len(self.pattern): raise ValueError("Trailing backslash")
                        end_char = self.pattern[pos+1]
                        pos += 2
                    else:
                        end_char = self.pattern[pos]
                        pos += 1
                    if ord(char) > ord(end_char): raise ValueError("Invalid range")
                    ranges.append((ord(char), ord(end_char)))
                else:
                    ranges.append((ord(char), ord(char)))
            else:
                ranges.append((ord(char), ord(char)))
        raise ValueError("Unclosed [")

def epsilon_closure(states, index, text_len):
    closure = set(states)
    stack = list(states)
    while stack:
        s = stack.pop()
        if isinstance(s, SplitState):
            for next_s in (s.s1, s.s2):
                if next_s not in closure:
                    closure.add(next_s)
                    stack.append(next_s)
        elif isinstance(s, AnchorStartState):
            if index == 0:
                if s.target not in closure:
                    closure.add(s.target)
                    stack.append(s.target)
        elif isinstance(s, AnchorEndState):
            if index == text_len:
                if s.target not in closure:
                    closure.add(s.target)
                    stack.append(s.target)
        elif isinstance(s, State):
            for next_s in s.next:
                if next_s not in closure:
                    closure.add(next_s)
                    stack.append(next_s)
    return closure

def regex_search(pattern: str, text: str) -> bool:
    if not pattern: return True
    try:
        parser = Parser(pattern)
        frag = parser.parse_expr_fixed()
        if parser.pos < len(parser.pattern):
            raise ValueError("Unclosed parenthesis or extra characters")
    except (ValueError, IndexError):
        raise ValueError("Invalid pattern")

    nfa_start, nfa_end = frag.start, frag.end

    if not pattern.startswith('^'):
        s_search_start = SplitState(nfa_start, None)
        s_any = DotState(s_search_start)
        s_search_start.s2 = s_any
        start_state = s_search_start
    else:
        start_state = nfa_start

    current_states = epsilon_closure({start_state}, 0, len(text))
    if nfa_end in current_states: return True

    for i, char in enumerate(text):
        next_states = set()
        for s in current_states:
            if isinstance(s, CharState) and s.char == char:
                next_states.add(s.target)
            elif isinstance(s, DotState):
                next_states.add(s.target)
            elif isinstance(s, ClassState):
                if s.matches(char):
                    next_states.add(s.target)
        current_states = epsilon_closure(next_states, i + 1, len(text))
        if nfa_end in current_states: return True

    return False
